/** The Keyrook server this build talks to, fixed at build time (scripts/api.mjs). */
declare const __KEYROOK_API__: string;
/** The RP ID of the Keyrook account's passkeys, for that server (scripts/api.mjs). */
declare const __KEYROOK_ACCOUNT_RP__: string;
/** The account's page beside that server, where Passhold's links go (scripts/api.mjs). */
declare const __KEYROOK_ACCOUNT_PAGE__: string;
/** Passhold's web vault beside that server, where no script of Passhold's runs (scripts/api.mjs). */
declare const __KEYROOK_VAULT_PAGE__: string;
/** Where a Send's link opens for that server (scripts/api.mjs). */
declare const __KEYROOK_SEND_PAGE__: string;
